import urllib.request, xml.etree.ElementTree as ET
from collections import Counter
ns={'s':'http://www.sitemaps.org/schemas/sitemap/0.9'}

def urls(name):
    raw=urllib.request.urlopen(f'https://respond.io/{name}', timeout=120).read()
    r=ET.fromstring(raw)
    return [u.text for u in r.findall('.//s:loc',ns)]

known={'es','ar','zh','tw','fr','de','id','it','pt','ru','th','vi','tr','ja','ko','nl','pl','ms'}

for sm in ['sitemap-blogs.xml','sitemap-help-articles.xml','sitemap-tags.xml','sitemap-video-tutorial.xml']:
    u=urls(sm)
    loc=Counter(); samples=[]
    for x in u:
        path=x.replace('https://respond.io/','').rstrip('/')
        parts=path.split('/')
        if parts[0] in known:
            loc[parts[0]]+=1
            if len(samples)<3 and parts[0]=='es': samples.append('/'+path)
        else:
            loc['en']+=1
            if len(samples)<3 and 'es' not in path: samples.append('/'+path)
    print(sm, 'total', len(u), 'locales', dict(loc.most_common()))
    print('  samples', samples[:3])
    # structure of EN blog
    if 'blog' in sm:
        en=[x for x in u if not x.replace('https://respond.io/','').split('/')[0] in known]
        print('  en sample', [e.replace('https://respond.io','') for e in en[:5]])
        print('  es sample', [e.replace('https://respond.io','') for e in u if '/es/' in e][:5])

# builder.io density on a few page types
import re
req=lambda url: urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent':'Mozilla/5.0'}), timeout=30).read().decode('utf-8','replace')
for url in ['https://respond.io/pricing','https://respond.io/blog','https://respond.io/help','https://respond.io/integrations']:
    try:
        html=req(url)
        print(url, 'astro', 'Astro' in html or '_astro' in html, 'builder hits', len(re.findall(r'builder', html, re.I)), 'len', len(html))
    except Exception as e:
        print(url, e)
